import {
	Component,
	Element,
	Event,
	EventEmitter,
	Host,
	Prop,
	Watch,
	h,
} from "@stencil/core";
import { clamp } from "../../utils/function-helper";

interface FocusableHTMLElement extends HTMLElement {
	setFocus(): void;
}

function getChildrenItems({
	treeItem,
	includeDisabled = true,
	includeUnselectable = true,
}: {
	treeItem?: HTMLHbrTreeItemElement;
	includeDisabled?: boolean;
	includeUnselectable?: boolean;
} = {}): HTMLHbrTreeItemElement[] {
	const childrenSlot = treeItem.shadowRoot?.querySelector(
		"slot[name=children]",
	);
	return childrenSlot
		? // @ts-ignore
		  ([...childrenSlot.assignedElements({ flatten: true })].filter(
				// @ts-ignore
				(item: HTMLHbrTreeItemElement) =>
					isTreeItem(item) &&
					(includeDisabled || !item.disabled) &&
					(includeUnselectable || !item.unselectable),
		  ) as HTMLHbrTreeItemElement[])
		: [];
}

function isTreeItem(node: HTMLElement) {
	return (
		node instanceof HTMLElement && node.getAttribute("role") === "treeitem"
	);
}

function syncCheckboxes(
	changedTreeItem: HTMLHbrTreeItemElement,
	initialSync = false,
) {
	function syncParentItem(treeItem: HTMLHbrTreeItemElement) {
		// When a parent has children hidden by an active filter, its selected/
		// indeterminate state cannot be derived from its visible children alone.
		// Defer to the consumer-controlled state (computed from the full data set)
		// so a category is never shown as fully selected while hidden children
		// remain unselected.
		if (treeItem.filtered) {
			return;
		}

		const children = getChildrenItems({
			treeItem,
			includeDisabled: false,
			includeUnselectable: true,
		});

		if (children.length) {
			const allChecked = children.every((item) => item.selected);
			const allUnchecked = children.every(
				(item) => !item.selected && !item.indeterminate,
			);

			treeItem.selected = allChecked;
			treeItem.indeterminate = !allChecked && !allUnchecked;
		}
	}

	function syncAncestors(treeItem: HTMLHbrTreeItemElement) {
		const parentItem: HTMLHbrTreeItemElement | null =
			treeItem.parentElement as HTMLHbrTreeItemElement;

		if (isTreeItem(parentItem)) {
			syncParentItem(parentItem);
			syncAncestors(parentItem);
		}
	}

	function syncDescendants(treeItem: HTMLHbrTreeItemElement) {
		const children = getChildrenItems({ treeItem });
		for (const childItem of children) {
			childItem.selected = initialSync
				? treeItem.selected || childItem.selected
				: !childItem.disabled && treeItem.selected;

			syncDescendants(childItem);
		}

		if (initialSync) {
			syncParentItem(treeItem);
		}
	}

	syncDescendants(changedTreeItem);
	syncAncestors(changedTreeItem);
}

/**
 * @summary Trees allow you to display a hierarchical list of selectable [tree items](/components/tree-item). Items with children can be expanded and collapsed as desired by the user.
 * @documentation https://shoelace.style/components/tree
 * @status stable
 * @since 2.0
 *
 * @event {{ selection: HTMLHbrTreeItemElement[] }} hbr-selection-change - Emitted when a tree item is selected or deselected.
 *
 * @slot - The default slot.
 * @slot expand-icon - The icon to show when the tree item is expanded. Works best with `<hbr-icon>`.
 * @slot collapse-icon - The icon to show when the tree item is collapsed. Works best with `<hbr-icon>`.
 *
 * @csspart base - The component's base wrapper.
 *
 * @cssproperty [--indent-size=var(--hbr-spacing-medium)] - The size of the indentation for nested items.
 * @cssproperty [--indent-guide-color=var(--base-border-default)] - The color of the indentation line.
 * @cssproperty [--indent-guide-offset=0] - The amount of vertical spacing to leave between the top and bottom of the
 *  indentation line's starting position.
 * @cssproperty [--indent-guide-style=solid] - The style of the indentation line, e.g. solid, dotted, dashed.
 * @cssproperty [--indent-guide-width=0] - The width of the indentation line.
 */
@Component({
	tag: "hbr-tree",
	styleUrl: "tree.scss",
	shadow: true,
})
export class HbrTree {
	@Element() host: HTMLHbrTreeElement;
	defaultSlot: Element;
	expandedIconSlot: Element;
	collapsedIconSlot: Element;

	/**
	 * The selection behavior of the tree. Single selection allows only one node to be selected at a time. Multiple
	 * displays checkboxes and allows more than one node to be selected. Leaf allows only leaf nodes to be selected.
	 */
	@Prop({ reflect: true }) selection: "single" | "multiple" | "leaf" = "single";

	/**
	 * The size of the tree.
	 */
	@Prop({ reflect: true }) size: "small" | "medium" = "medium";

	/**
	 * The variant of the tree. This will determine the style of the tree.
	 */
	@Prop({ reflect: true }) variant: undefined | "tab" = undefined;

	/** Emitted after the tree item lazily changes */
	@Event({ eventName: "hbr-selection-change" })
	hbrSelectionChange: EventEmitter;

	//
	// A collection of all the items in the tree, in the order they appear. The collection is live, meaning it is
	// automatically updated when the underlying document is changed.
	//
	private lastFocusedItem: HTMLHbrTreeItemElement | null;
	private firstFocusableItem: HTMLHbrTreeItemElement | null = null;
	//   private readonly localize = new LocalizeController(this);
	private mutationObserver: MutationObserver;

	connectedCallback() {
		this.host.addEventListener("focusin", this.handleFocusIn);
		this.host.addEventListener("focusout", this.handleFocusOut);
		this.handleSlotChange = this.handleSlotChange.bind(this);
		this.host.addEventListener("hbr-lazy-change", this.handleLazyChange);

		this.host.setAttribute("role", "tree");
		this.host.setAttribute("tabindex", "0");

		// await this.updateComplete;

		this.mutationObserver = new MutationObserver(this.handleTreeChanged);
		this.mutationObserver.observe(this.host, {
			childList: true,
			subtree: true,
		});

		this.handleClick = this.handleClick.bind(this);
		this.handleKeyDown = this.handleKeyDown.bind(this);
	}

	disconnectedCallback() {
		this.mutationObserver.disconnect();
	}

	// Generates a clone of the expand icon element to use for each tree item
	private getExpandButtonIcon(status: "expand" | "collapse") {
		const slot = (
			status === "expand" ? this.expandedIconSlot : this.collapsedIconSlot
		) as HTMLSlotElement;
		const icon = slot.assignedElements({ flatten: true })[0] as HTMLElement;

		// Clone it, remove ids, and slot it
		if (icon) {
			const clone = icon.cloneNode(true) as HTMLElement;
			[clone, ...clone.querySelectorAll("[id]")].forEach((el) =>
				el.removeAttribute("id"),
			);
			clone.setAttribute("data-default", "");
			clone.slot = `${status}-icon`;

			return clone;
		}

		return null;
	}

	// Initializes new items by setting the `selectable` property and the expanded/collapsed icons if any
	private initTreeItem = (item: HTMLHbrTreeItemElement) => {
		item.selectable = this.selection === "multiple";

		["expand", "collapse"]
			.filter((status) => !!this.host.querySelector(`[slot="${status}-icon"]`))
			.forEach((status: "expand" | "collapse") => {
				const existingIcon = item.querySelector(`[slot="${status}-icon"]`);

				const expandButtonIcon = this.getExpandButtonIcon(status);

				if (!expandButtonIcon) return;

				if (existingIcon === null) {
					// No separator exists, add one
					item.append(expandButtonIcon);
				} else if (existingIcon.hasAttribute("data-default")) {
					// A default separator exists, replace it
					existingIcon.replaceWith(expandButtonIcon);
				} else {
					// The user provided a custom icon, leave it alone
				}
			});
	};

	private handleTreeChanged = (mutations: MutationRecord[]) => {
		for (const mutation of mutations) {
			const addedNodes: HTMLHbrTreeItemElement[] = [
				...mutation.addedNodes,
			].filter(isTreeItem) as HTMLHbrTreeItemElement[];
			const removedNodes = [...mutation.removedNodes].filter(
				isTreeItem,
			) as HTMLHbrTreeItemElement[];

			addedNodes.forEach(this.initTreeItem);

			if (this.lastFocusedItem && removedNodes.includes(this.lastFocusedItem)) {
				this.lastFocusedItem = null;
			}
		}
	};

	private selectItem(selectedItem: HTMLHbrTreeItemElement) {
		const previousSelection = [...this.selectedItems];

		if (this.selection === "multiple") {
			selectedItem.selected = !selectedItem.selected;
			if (selectedItem.lazy) {
				selectedItem.expanded = true;
			}
			syncCheckboxes(selectedItem);
		} else if (this.selection === "single") {
			const items = this.getAllTreeItems();
			for (const item of items) {
				item.selected = item === selectedItem;
			}
		} else if (this.selection === "leaf") {
			const items = this.getAllTreeItems();
			for (const item of items) {
				item.selected = item === selectedItem;
			}
		}

		const nextSelection = this.selectedItems;
		if (
			previousSelection.length !== nextSelection.length ||
			nextSelection.some((item) => !previousSelection.includes(item))
		) {
			// // Wait for the tree items' DOM to update before emitting
			// Promise.all(nextSelection.map(el => el.updateComplete)).then(() => {
			//     this.emit('hbr-selection-change', { detail: { selection: nextSelection } });
			// });
			this.hbrSelectionChange.emit({ selection: nextSelection });
		}
	}

	private getAllTreeItems() {
		return [
			...this.host.querySelectorAll<HTMLHbrTreeItemElement>("hbr-tree-item"),
		];
	}

	private focusItem(item?: HTMLHbrTreeItemElement | null) {
		item?.focus();
	}

	private findNextTreeItem(currentEl: Element | null): HTMLElement | null {
		if (!currentEl) return null;

		// Make sure we are starting from a tree item, not from an interactive child
		const treeItem = currentEl.closest(
			"hbr-tree-item",
		) as HTMLHbrTreeItemElement | null;
		if (!treeItem) return null;

		// Step 1: If the tree item is expanded and has child tree-items, go to first child
		const isCollapsed = treeItem.expanded === false;
		if (!isCollapsed) {
			const childTreeItem = treeItem.querySelector(":scope > hbr-tree-item");
			if (childTreeItem) {
				return childTreeItem as HTMLElement;
			}
		}

		// Step 2: If no child or collapsed, check next sibling
		let nextSibling = treeItem.nextElementSibling;
		while (nextSibling) {
			if (nextSibling.tagName === "HBR-TREE-ITEM") {
				return nextSibling as HTMLElement;
			}
			nextSibling = nextSibling.nextElementSibling;
		}

		// Step 3: If no next sibling, climb up to parent tree-items and look for their next siblings
		let parent = treeItem.parentElement;
		while (parent) {
			const parentTreeItem = parent.closest(
				"hbr-tree-item",
			) as HTMLHbrTreeItemElement | null;
			if (parentTreeItem) {
				let parentNextSibling = parentTreeItem.nextElementSibling;
				while (parentNextSibling) {
					if (parentNextSibling.tagName === "HBR-TREE-ITEM") {
						return parentNextSibling as HTMLElement;
					}
					parentNextSibling = parentNextSibling.nextElementSibling;
				}
			}
			parent = parent.parentElement;
		}

		// No next tree item found
		return null;
	}

	private findPreviousTreeItem(currentEl: Element | null): HTMLElement | null {
		if (!currentEl) return null;

		// Start from closest hbr-tree-item
		const treeItem = currentEl.closest(
			"hbr-tree-item",
		) as HTMLHbrTreeItemElement | null;
		if (!treeItem) return null;

		// Step 1: Check previous siblings
		let prevSibling = treeItem.previousElementSibling;
		while (prevSibling) {
			if (prevSibling.tagName === "HBR-TREE-ITEM") {
				let candidate = prevSibling as HTMLHbrTreeItemElement;

				// Dive into the last expanded child
				while (true) {
					// Check if the candidate is expanded
					const isCollapsed = !candidate.expanded;
					const children = isCollapsed
						? []
						: Array.from(candidate.querySelectorAll(":scope > hbr-tree-item"));

					if (children.length > 0) {
						candidate = children[children.length - 1] as HTMLHbrTreeItemElement;
					} else {
						break;
					}
				}

				return candidate;
			}
			prevSibling = prevSibling.previousElementSibling;
		}

		// Step 2: No previous sibling — climb up to parent
		const parentTreeItem = treeItem.parentElement?.closest(
			"hbr-tree-item",
		) as HTMLHbrTreeItemElement | null;
		return parentTreeItem || null;
	}

	private handleArrowUpNavigation(
		event: KeyboardEvent,
		activeItemIndex: number,
		items: HTMLHbrTreeItemElement[],
	) {
		const focusItemAt = (index: number) => {
			const item = items[clamp(index, 0, items.length - 1)];
			this.focusItem(item);
		};

		const focusedElement = event.target as HTMLElement;
		const currentTreeItem = focusedElement.closest(
			"hbr-tree-item",
		) as HTMLHbrTreeItemElement | null;

		if (!currentTreeItem) return;

		// Case 1: Focus is inside dropdown (NOT on tree item itself)
		if (focusedElement !== currentTreeItem) {
			currentTreeItem.focus(); // Move focus back to parent tree item
			return;
		}

		// Case 2: Focus is already on tree item itself
		const prevTreeItem = this.findPreviousTreeItem(currentTreeItem);

		if (prevTreeItem) {
			// Now prevTreeItem is the right one to focus
			// Look for first focusable interactive element inside its suffix
			const suffixSlot = prevTreeItem.shadowRoot?.querySelector(
				'slot[name="interactive"]',
			);
			let focusables: FocusableHTMLElement[] = [];

			if (suffixSlot) {
				const assignedElements = (
					suffixSlot as HTMLSlotElement
				).assignedElements({ flatten: true });
				assignedElements.forEach((el) => {
					focusables = focusables.concat(this.getInteractiveElements(el));
				});
			}

			const firstFocusable = focusables[0] as FocusableHTMLElement | undefined;

			if (firstFocusable) {
				firstFocusable.setFocus();
			} else {
				prevTreeItem.focus();
			}
		} else {
			// No previous tree item, just focus normally upwards
			focusItemAt(activeItemIndex - 1);
		}
	}

	private handleArrowDownNavigation(
		event: KeyboardEvent,
		activeItem: HTMLHbrTreeItemElement | undefined,
		activeItemIndex: number,
		items: HTMLHbrTreeItemElement[],
		// direction: "up" | "down"
	) {
		const focusItemAt = (index: number) => {
			const item = items[clamp(index, 0, items.length - 1)];
			this.focusItem(item);
		};

		let focusables: FocusableHTMLElement[] = [];

		if (activeItem) {
			const suffixSlot = activeItem.shadowRoot?.querySelector(
				'slot[name="interactive"]',
			);
			if (suffixSlot) {
				const assignedElements = (
					suffixSlot as HTMLSlotElement
				).assignedElements({ flatten: true });
				assignedElements.forEach((el) => {
					const elements = this.getInteractiveElements(el);
					focusables = focusables.concat(elements);
				});
			}
		}

		const firstFocusable = focusables[0] as FocusableHTMLElement | undefined;

		// const isArrowDown = direction === "down";
		// const isArrowUp = direction === "up";

		const targetIndex = focusables.findIndex(
			(el) => el === event.target || el.contains(event.target as Node),
		);

		const isLastFocusable =
			targetIndex !== -1 && targetIndex === focusables.length - 1;

		if (activeItem && event.target === activeItem) {
			if (firstFocusable) {
				firstFocusable.setFocus();
			} else {
				focusItemAt(activeItemIndex + 1);
			}
		} else if (
			focusables.includes(event.target as FocusableHTMLElement) ||
			targetIndex !== -1
		) {
			if (isLastFocusable) {
				event.preventDefault();
				return;
			}
		} else {
			const nextTreeItem = this.findNextTreeItem(event.target as Element);

			if (nextTreeItem) {
				nextTreeItem.focus();
			} else {
				return;
			}
		}
	}

	private handleKeyDown(event: KeyboardEvent) {
		// Ignore key presses we aren't interested in
		if (
			![
				"ArrowDown",
				"ArrowUp",
				"ArrowRight",
				"ArrowLeft",
				"Home",
				"End",
				"Enter",
				" ",
			].includes(event.key)
		) {
			return;
		}

		// Ignore key presses when focus is inside a text field. This prevents the component from hijacking nested form
		// controls that exist inside tree items.
		if (
			event
				.composedPath()
				.some((el: HTMLElement) =>
					["input", "textarea"].includes(el?.tagName?.toLowerCase()),
				)
		) {
			return;
		}

		const items = this.getFocusableItems();
		const isLtr = true;
		const isRtl = false;

		if (items.length > 0) {
			event.preventDefault();
			const activeItemIndex = items.findIndex((item) => item.matches(":focus"));

			const activeItem: HTMLHbrTreeItemElement | undefined =
				items[activeItemIndex];

			const focusItemAt = (index: number) => {
				const item = items[clamp(index, 0, items.length - 1)];
				this.focusItem(item);
			};
			const toggleExpand = (expanded: boolean) => {
				activeItem.expanded = expanded;
			};

			if (event.key === "ArrowDown") {
				this.handleArrowDownNavigation(
					event,
					activeItem,
					activeItemIndex,
					items,
				);
			} else if (event.key === "ArrowUp") {
				// Moves focus to the next node that is focusable without opening or closing a node.
				this.handleArrowUpNavigation(event, activeItemIndex, items);
				// “Right” in LTR (ArrowRight) or “Left” in RTL (ArrowLeft):
				//  • Collapsed + non‐leaf → expand
				//  • Expanded       → focus first child
				//  • Leaf           → do nothing
			} else if (
				(isLtr && event.key === "ArrowRight") ||
				(isRtl && event.key === "ArrowLeft")
			) {
				event.preventDefault();
				if (!activeItem || activeItem.disabled) return;

				// leaf nodes do nothing
				if (activeItem.leaf && !activeItem.lazy) return;

				if (!activeItem.expanded) {
					// collapsed node → expand
					toggleExpand(true);
				} else {
					// expanded node → move focus to its first child
					focusItemAt(activeItemIndex + 1);
				}

				// “Left” in LTR (ArrowLeft) or “Right” in RTL (ArrowRight):
				//  • Expanded       → collapse
				//  • Collapsed/leaf → move focus to parent (unless root)
				//  • Root           → do nothing
			} else if (
				(isLtr && event.key === "ArrowLeft") ||
				(isRtl && event.key === "ArrowRight")
			) {
				event.preventDefault();
				if (!activeItem || activeItem.disabled) return;

				if (activeItem.expanded) {
					// expanded node → collapse
					toggleExpand(false);
					return;
				}

				// Find parent tree‐item (if any)
				const parent = activeItem
					.closest("hbr-tree-item")
					?.parentElement?.closest("hbr-tree-item") as HTMLElement | null;

				if (!parent) {
					// no parent (i.e. at root) → do nothing
					return;
				}

				// move focus to parent’s index in the flat items array
				const parentIndex = items.findIndex((item) => item === parent);
				if (parentIndex >= 0) {
					focusItemAt(parentIndex);
				}
			} else if (event.key === "Home") {
				// Moves focus to the first node in the tree without opening or closing a node.
				focusItemAt(0);
			} else if (event.key === "End") {
				// Moves focus to the last node in the tree that is focusable without opening the node.
				focusItemAt(items.length - 1);
			} else if (event.key === "Enter" || event.key === " ") {
				if (!activeItem) return;
				// Selects the focused node.
				if (!activeItem.disabled) {
					this.selectItem(activeItem);
				}
			}
		}
	}

	private handleClick(event: Event) {
		const target = event.target as HTMLHbrTreeItemElement;
		const treeItem = target.closest(
			"hbr-tree-item",
		) as HTMLHbrTreeItemElement | null;
		const isExpandButton = event
			.composedPath()
			.some(
				(el: HTMLElement) =>
					el?.classList?.contains("tree-item__expand-button") ||
					el?.getAttribute?.("slot") === "expand-icon" ||
					el?.getAttribute?.("slot") === "collapse-icon",
			);

		//
		// Don't Do anything if there's no tree item, if it's disabled, or if the click doesn't match the initial target
		// from mousedown. The latter case prevents the user from starting a click on one item and ending it on another,
		// causing the parent node to collapse.
		//
		// See https://github.com/shoelace-style/shoelace/issues/1082
		//
		// if (!treeItem || treeItem.disabled || target !== this.clickTarget) {
		// 	return;
		// }

		if (!treeItem || treeItem.disabled) {
			return;
		}

		if (isExpandButton) {
			treeItem.expanded = !treeItem.expanded;
		} else if (treeItem.unselectable) {
			return;
		} else {
			// In leaf mode, ignore clicks on parent (non-leaf) or lazy nodes; only allow selecting true leaves
			if (this.selection === "leaf" && (!treeItem.leaf || treeItem.lazy)) {
				return;
			}
			this.selectItem(treeItem);
		}
	}

	private handleFocusOut = (event: FocusEvent) => {
		const relatedTarget = event.relatedTarget as HTMLElement;

		// If the element that got the focus is not in the tree
		if (!relatedTarget || !this.host.contains(relatedTarget)) {
			this.host.tabIndex = 0;
		}
	};

	private handleFocusIn = (event: FocusEvent) => {
		const target = event.target as HTMLHbrTreeItemElement;
		// If the tree has been focused, move the focus to the first focused item
		if (event.target === this.host) {
			if (!this.firstFocusableItem) {
				this.firstFocusableItem =
					this.getAllTreeItems().find((item) => item.selected) ||
					this.getAllTreeItems()[0];
			}
			if (this.firstFocusableItem) {
				this.focusItem(this.firstFocusableItem);
			}
		}

		// If the target is a tree item, update the tabindex
		if (isTreeItem(target) && !target.disabled) {
			if (this.lastFocusedItem) {
				this.lastFocusedItem.tabIndex = -1;
			}
			// this.firstFocusableItem = this.getFirstFocusableItem();
			this.lastFocusedItem = target;
			this.host.tabIndex = -1;

			target.tabIndex = 0;
		}
	};

	private handleSlotChange() {
		const items = this.getAllTreeItems();
		items.forEach(this.initTreeItem);
	}

	private handleLazyChange = (event: Event) => {
		this.handleSlotChange();

		const treeItem = event.target as HTMLHbrTreeItemElement;
		if (
			this.selection !== "multiple" ||
			!isTreeItem(treeItem) ||
			treeItem.lazy
		) {
			return;
		}

		requestAnimationFrame(() => {
			requestAnimationFrame(() => {
				if (this.host.isConnected) {
					for (const childItem of treeItem.querySelectorAll<HTMLHbrTreeItemElement>(
						"hbr-tree-item",
					)) {
						childItem.selected = treeItem.selected || childItem.selected;
					}

					syncCheckboxes(treeItem, true);
				}
			});
		});
	};

	@Watch("selection")
	async handleSelectionChange() {
		const isSelectionMultiple = this.selection === "multiple";
		const items = this.getAllTreeItems();

		this.host.setAttribute(
			"aria-multiselectable",
			isSelectionMultiple ? "true" : "false",
		);

		for (const item of items) {
			item.selectable = isSelectionMultiple;
		}

		if (isSelectionMultiple) {
			// await this.updateComplete;

			[...this.host.querySelectorAll(":scope > hbr-tree-item")].forEach(
				(treeItem: HTMLHbrTreeItemElement) => syncCheckboxes(treeItem, true),
			);
		}
	}

	/** @internal Returns the list of tree items that are selected in the tree. */
	get selectedItems(): HTMLHbrTreeItemElement[] {
		const items = this.getAllTreeItems();
		const isSelected = (item: HTMLHbrTreeItemElement) => item.selected;

		return items.filter(isSelected);
	}

	getInteractiveElements(root: Element | ShadowRoot): FocusableHTMLElement[] {
		const focusable: FocusableHTMLElement[] = [];

		const walker = document.createTreeWalker(root, NodeFilter.SHOW_ELEMENT, {
			acceptNode(node) {
				const el = node as FocusableHTMLElement;
				return typeof (el as FocusableHTMLElement).setFocus === "function"
					? NodeFilter.FILTER_ACCEPT
					: NodeFilter.FILTER_SKIP;
			},
		});

		let currentNode = walker.nextNode();
		while (currentNode) {
			focusable.push(currentNode as FocusableHTMLElement);
			currentNode = walker.nextNode();
		}

		return focusable;
	}

	/** @internal Gets focusable tree items in the tree. */
	getFocusableItems() {
		const items = this.getAllTreeItems();
		const collapsedItems = new Set();

		return items.filter((item) => {
			// Exclude disabled elements
			if (item.disabled) return false;

			// Exclude those whose parent is collapsed or loading
			const parent: HTMLHbrTreeItemElement | null | undefined =
				item.parentElement?.closest("[role=treeitem]");
			if (
				parent &&
				(!parent.expanded || parent.loading || collapsedItems.has(parent))
			) {
				collapsedItems.add(item);
			}

			return !collapsedItems.has(item);
		});
	}

	render() {
		return (
			<Host role="tree">
				<div
					part="base"
					class={{
						tree: true,
						"tree-tabs": this.variant === "tab",
					}}
					onClick={this.handleClick}
					onKeyDown={this.handleKeyDown}
				>
					<slot onSlotchange={this.handleSlotChange} />
					<span hidden aria-hidden="true">
						<slot
							name="expand-icon"
							ref={(el) => {
								this.expandedIconSlot = el;
							}}
						/>
					</span>
					<span hidden aria-hidden="true">
						<slot
							name="collapse-icon"
							ref={(el) => {
								this.collapsedIconSlot = el;
							}}
						/>
					</span>
				</div>
			</Host>
		);
	}
}
